let raw = $input.first().json.output;

// Remove Markdown code fences (```json ... ```)
raw = raw.replace(/```(?:json)?\n?/, '').replace(/```$/, '').trim();

let cleaned = {};
try {
  cleaned = JSON.parse(raw);
} catch (err) {
  // fallback if parsing still fails
  cleaned = {};
}

return [
  {
    json: cleaned
  }
];
